window.POETRY_REGISTER("v5-strict-9-5-0-f67d8b296eda.js",{"poems":[[3308,2],[9836,2],[9864,2],[19859,2],[22501,2],[22585,2],[23555,2],[37488,2],[40381,2],[44965,2],[52700,2],[54187,2],[57649,2],[59041,7],[59078,7],[67145,7],[69153,7],[69569,7],[69572,7],[75317,7],[77898,7],[77899,7],[78316,7],[78629,7],[83034,7],[97664,7],[104970,7],[112289,7],[136815,7],[136923,7],[163389,7],[187780,7],[192127,7],[233437,7],[234165,7],[257448,7],[271683,7],[272127,7],[304461,7],[325718,7],[335919,9],[345936,9],[351007,9],[368344,10],[369879,10],[375208,10],[375210,10],[399793,8],[403882,8],[406518,8],[413226,8],[453827,8],[460781,8],[466720,8],[466754,8],[467789,8],[473644,8],[504999,8],[505350,8],[532111,8],[547336,8],[581843,8],[587820,8],[614666,8],[625634,8],[634649,15],[635962,15],[637840,15],[647863,15],[660342,5],[662752,5],[663630,5],[684303,5],[685562,5],[700083,5],[700160,5],[701886,5],[711261,5],[728140,5],[729800,5],[735537,5],[737332,19]],"pairs":[["轩后爪牙常先太山稽","如心之使臂",0],["天子九九八十一万岁","长倾万岁杯",1],["轩后爪牙尝先太山稽","如心之使臂",2],["玉川子立于庭而言曰","地行贱臣仝",3],["鸟为居停主人不觉察","贪向何人家",4],["听我暂话会稽朱太守","正受冻饿时",5],["天遣食牛吞象充腹肠","蛟螭与变化",6],["我闻周公贵为天子弟","富有半四海",7],["又岂复忧朝廷苦弛慢","中官转纵横",8],["未若此调呦呦兮啁啁","嘈嘈兮啾啾",9],["盖从当时渤海藩国言","故曰在唐也",10],["末二句作莫欣黄雀至","须惮微躯伤",11],["原刻为政和间人磨去","今仅存残文",12],["向鸡窗只与蛮笺象管","拘束教吟课",13],["算神仙五色灵丹无验","中路委瓶簪",14],["向吴天万里一叶归舟","岁月尽悠悠",15],["算静中唯有窗间梅影","合是幽人伴",16],["放曲屏珠幌胆瓶儿里","伴我醺醺睡",17],["怎奈向天与孤高出众","一任傍人恶",18],["便饶他百计千方就做","酝藉如何学",18],["澄江上几度啸日迎风","怡怡钓秋色",19],["恨马融一声羌笛起处","纷纷落如雪",20],["向深冬免使游蜂舞蝶","撩拨春心乱",21],["后头没一句说著朝廷","尽把师归美",22],["蓬莱邃馆金碧照三山","真境胜人间",23],["方知安侯不是星辰类","即是神仙辈",24],["留此玉轮之迹在青壁","风雨不可剥",25],["请君为我细书字于侧","名为月母峰",26],["上有横河断海之浮云","可望不可攀",27],["以长觜鸟啄其心肝肺","乃退藏于密",28],["自为𬬻而镕凡圣之铜","乃将图南也",28],["予爱兰而莫与予佩兮","曰斯其不情",29],["我谓鹓雏排风整毛质","翦拂始光辉",30],["安得身有羽翼如鸳鸯","千里同相将",31],["吾不能移王屋之山兮","通褒斜之阪",32],["神羊不世有以触邪兮","其谁宜为政",33],["度钱塘兮江碧而山苍","斯行兮非常",34],["何似祇今握手见肺肝","开口无毁誉",35],["自今永永三十六万岁","淳古比九皇",36],["毋宁以家而忘此匈奴","岂其私是图",37],["不是心不是佛不是物","贬向无生国",38],["我亦有耳但愿听松风","有口只饮酒",39],["酬和情诗玉宇净无尘","宝月圆如镜",40],["争如芝田野老衣悬鹑","饥撷芝术餐",41],["仙之人兮须为谢安石","莫学王子猷",42],["东海之东去国十万里","其洲名沧洲",43],["女乃不知日被黑子遮","月为妖蟆食",44],["君不见魏其侯门下客","独厚灌太仆",45],["呜呼今丈夫弃耕贪禄","粟万钟养孥",46],["眼睁睁望着灯前壁上","壁上形怜影",47],["尝闻乐府牡丹芳春来","一城人若狂",48],["不然上天纵尔九苞羽","安用毰毸为",49],["嗟哉希直执经太史门","闻礼济宁庭",50],["下有万古不定之龙沙","风滚无时休",51],["下有元精山灵秘流膏","入土今千年",52],["人云鲸波山立而血人","安能远相期",53],["乃不知东有属玉䴔䴖","西有鸥与鹭",54],["男儿生不能学向子平","弃家游五岳",55],["团结党类以俟我衅隙","为我子孙慝",56],["是时我行自南复之东","二物真相从",57],["嗟彼小人无才为稂莠","有才为荆葵",58],["更有芝兰浥露寄光金","掩映看陆离",59],["相似今日大棍乱打人","恶口乱骂人",60],["半载悠悠客京索千钱","僦得城南庐",61],["此君所以为三友之一","流万世之芳",62],["乃不知东有属玉䴔䴖","西有鸥与鹭",63],["团结党类以俟我衅隙","为我子孙慝",64],["拖逗得伤心染就残痕","到如今消受",65],["怎想像梦里姚姬不管","深宫细腰苦",66],["何不脱君见肘之玄端","为我冬杅复",67],["与盘中红蓿芬馨共啖","谁似儒官好",68],["二语本邵坤道善承天","诸福载应广",69],["以追少陵大有作为作","磁铁两孚召",70],["而况人世之得失穷通","一一归虚空",71],["刚得教成歌舞如花艳","送入馆娃宫",72],["无奈君王薪胆催人去","遣作馆娃春",73],["无赖唯馀石上青苔迹","千载解愁人",73],["愿倾城世外佳人一笑","羌笛须回避",74],["待些时折取长条一枝","寄征人万里",75],["汝以黄金散尽为复来","而乃鞭其脢",76],["我乃不知水神为俞儿","山鬼为冰夷",77],["淼淼夕阳金刹著波平","风光难画成",78],["闲锁阶前梅萼一枝横","僧雏学弄笙",78],["呜呼王虞部疏抗声读","一字一痛哭",79],["二语本邵坤道善承天","诸福载应广",80],["今尔胡为借甚乎人间","于嗟乎冷山",81]]});
